package vn.edu.crs.authservice.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
@Component public class JwtUtil{@Value("${jwt.secret}")String secret;@Value("${jwt.expiration-ms}")long exp;public String generate(Long userId,String u,String role){Date n=new Date();SecretKey k=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));return Jwts.builder().subject(u).claim("userId",userId).claim("role",role).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(k).compact();}}
